#pragma once
// Flappy - A or stick up = flap. Every 6 pipes: level up (faster, narrower). From level 3 the pipes float.
#define FB_ID 6
#define FB_PW 12
struct FbP { float x, gy, ph; bool passed; };
static FbP fbP[3]; static float fbY, fbVy; static uint16_t fbScore, fbHi; static uint8_t fbLvl, fbFr; static bool fbDead, fbStarted;
static int fbGap() { int g = 25 - fbLvl; return g < 16 ? 16 : g; }
static float fbSpd() { float s = 1.8f + 0.15f * fbLvl; return s > 3.2f ? 3.2f : s; }
static float fbGy(uint8_t i) {
  float g = fbP[i].gy; if (fbLvl >= 3) g += sinf(fbP[i].ph) * 6;
  float hi = 64 - 9 - fbGap(); if (g < 9) g = 9; if (g > hi) g = hi; return g;
}
static void fbNew(uint8_t i, float x) { fbP[i].x = x; fbP[i].gy = random(10, 64 - 9 - fbGap()); fbP[i].ph = random(628) / 100.0f; fbP[i].passed = false; }
static void fbInit() {
  fbY = 28; fbVy = 0; fbScore = 0; fbLvl = 1; fbFr = 0; fbDead = false; fbStarted = false; fbHi = hiGet(FB_ID);
  for (uint8_t i = 0; i < 3; i++) fbNew(i, 128 + i * 64);
}
static void fbUpdate() {
  if (fbDead) { if (overKeys()) fbInit(); return; }
  bool flap = in.aP || in.py < 0; fbFr++;
  if (!fbStarted) { if (flap) { fbStarted = true; fbVy = -3.0f; sfx(SFX_JUMP); } return; }
  if (flap) { fbVy = -3.0f; sfx(SFX_JUMP); }
  fbVy += 0.28f; if (fbVy > 4) fbVy = 4; fbY += fbVy;
  float sp = fbSpd();
  for (uint8_t i = 0; i < 3; i++) {
    fbP[i].x -= sp; fbP[i].ph += 0.06f;
    if (fbP[i].x < -FB_PW) fbNew(i, fbP[i].x + 192);
    if (!fbP[i].passed && fbP[i].x + FB_PW < 24) {
      fbP[i].passed = true; fbScore++;
      uint8_t nl = 1 + fbScore / 6;
      if (nl > fbLvl) { fbLvl = nl; bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); } else fx(SFX_COIN, C_GOLD, 80);
    }
    float gy = fbGy(i);
    if (24 + 8 > fbP[i].x && 24 < fbP[i].x + FB_PW && (fbY < gy || fbY + 6 > gy + fbGap())) fbDead = true;
  }
  if (fbY < 0 || fbY + 6 > 64) fbDead = true;
  if (fbDead) endRun(FB_ID, fbScore, fbHi);
}
static void fbDraw() {
  for (uint8_t i = 0; i < 3; i++) {
    int x = (int)fbP[i].x, gy = (int)fbGy(i), g = fbGap();
    u8g2.drawBox(x, 0, FB_PW, gy); u8g2.drawBox(x - 1, gy - 3, FB_PW + 2, 3);
    u8g2.drawBox(x, gy + g, FB_PW, 64 - gy - g); u8g2.drawBox(x - 1, gy + g, FB_PW + 2, 3);
  }
  int y = (int)fbY;
  u8g2.drawBox(24, y, 8, 6); u8g2.drawBox(32, y + 2, 2, 2);
  u8g2.setDrawColor(0); u8g2.drawPixel(29, y + 1); u8g2.drawBox(24, y + ((fbVy < 0) ? 1 : 3), 3, 1); u8g2.setDrawColor(1);
  char b[16]; snprintf(b, sizeof b, "%u", fbScore);
  u8g2.setDrawColor(0); u8g2.drawBox(52, 0, 24, 11); u8g2.setDrawColor(1); u8g2.setFont(FONT_M); textC(b, 9);
  if (!fbStarted) { u8g2.setFont(FONT_S); u8g2.setDrawColor(0); u8g2.drawBox(24, 53, 80, 10); u8g2.setDrawColor(1); textC("press A to flap", 61); }
  if (fbDead) overBox(fbScore, fbHi);
}
static void fbIcon(int x, int y) {
  u8g2.drawBox(x + 2, y + 12, 9, 7); u8g2.drawBox(x + 11, y + 14, 2, 2);
  u8g2.drawBox(x + 20, y, 8, 10); u8g2.drawBox(x + 19, y + 8, 10, 2); u8g2.drawBox(x + 20, y + 21, 8, 11); u8g2.drawBox(x + 19, y + 21, 10, 2);
}

#pragma once
// Rain Dodge: steer left/right to avoid falling blocks and collect stars.
#define DG_ID 13
static int8_t dgX;static int8_t dgOX[5],dgOY[5];static uint16_t dgScore,dgHi;static uint8_t dgLives;static bool dgOver;static uint32_t dgTick;
static void dgInit(){dgX=3;dgScore=0;dgHi=hiGet(DG_ID);dgLives=3;dgOver=false;dgTick=millis()+180;for(int i=0;i<5;i++){dgOX[i]=random(8);dgOY[i]=-random(64);}}
static void dgUpdate(){if(dgOver){if(overKeys())dgInit();return;}if(in.px){dgX+=in.px;if(dgX<0)dgX=0;if(dgX>7)dgX=7;}uint32_t now=millis();if((int32_t)(now-dgTick)>=0){dgTick=now+imax(55,180-dgScore/4);for(int i=0;i<5;i++){dgOY[i]++;if(dgOY[i]>=6){dgOY[i]=0;dgOX[i]=random(8);dgScore++;}if(dgOY[i]==5&&dgOX[i]==dgX){dgLives--;dgOY[i]=-random(5);dgOX[i]=random(8);sfx(SFX_HIT);if(!dgLives){dgOver=true;endRun(DG_ID,dgScore,dgHi);}}}}}
static void dgDraw(){char b[24];u8g2.setFont(FONT_S);snprintf(b,sizeof b,"SCORE %u  HP %u",dgScore,dgLives);textC(b,7);u8g2.drawFrame(0,10,128,53);for(int i=0;i<5;i++){int x=3+dgOX[i]*15,y=12+dgOY[i]*8;u8g2.drawBox(x+3,y,7,5);}int px=4+dgX*15;u8g2.drawTriangle(px+3,59,px,51,px+7,51);if(dgOver)overBox(dgScore,dgHi);}
static void dgIcon(int x,int y){u8g2.drawTriangle(x+16,y+27,x+6,y+8,x+26,y+8);u8g2.drawBox(x+13,y+2,6,5);u8g2.drawPixel(x+4,y+16);u8g2.drawPixel(x+28,y+22);}

#pragma once
// Snake - levels every 6 foods: faster + more rocks. Bonus star every 5th food (timed, worth 3).
#define SN_ID     4
#define SN_CW     32
#define SN_CH     14
#define SN_MAX    (SN_CW * SN_CH)
#define SN_STONES 24
static uint8_t snX[SN_MAX], snY[SN_MAX], stX[SN_STONES], stY[SN_STONES];
static uint16_t snLen, snScore, snHi, snEat; static uint8_t snStn, snLvl, snFx, snFy, snBx, snBy;
static int8_t snDx, snDy, snNx, snNy; static int16_t snBt; static bool snDead; static uint32_t snLast;

static bool snOcc(uint8_t x, uint8_t y) {
  for (uint16_t i = 0; i < snLen; i++) if (snX[i] == x && snY[i] == y) return true;
  for (uint8_t i = 0; i < snStn; i++) if (stX[i] == x && stY[i] == y) return true;
  return (x == snFx && y == snFy) || (snBt > 0 && x == snBx && y == snBy);
}
static void snPlace(uint8_t &ox, uint8_t &oy) {   // pick into temporaries: ox/oy may alias snFx/snBx
  uint8_t x, y; do { x = random(SN_CW); y = random(SN_CH); } while (snOcc(x, y)); ox = x; oy = y;
}
static void snInit() {
  snLen = 3; for (uint8_t i = 0; i < 3; i++) { snX[i] = 16 - i; snY[i] = 7; }
  snDx = snNx = 1; snDy = snNy = 0; snScore = 0; snEat = 0; snLvl = 1; snStn = 0; snBt = 0; snDead = false;
  snLast = millis(); snHi = hiGet(SN_ID); snFx = 255; snFy = 255; snPlace(snFx, snFy);
}
static void snAddStones() {
  for (uint8_t k = 0; k < 3 && snStn < SN_STONES; k++)
    for (uint8_t t = 0; t < 40; t++) {
      uint8_t x = random(SN_CW), y = random(SN_CH);
      if (abs((int)x - snX[0]) + abs((int)y - snY[0]) < 6 || snOcc(x, y)) continue;
      stX[snStn] = x; stY[snStn] = y; snStn++; break;
    }
}
static void snDie() { snDead = true; endRun(SN_ID, snScore, snHi); }
static void snUpdate() {
  if (snDead) { if (overKeys()) snInit(); return; }
  if (in.dx && snDx == 0) { snNx = in.dx; snNy = 0; } else if (in.dy && snDy == 0) { snNx = 0; snNy = in.dy; }
  if (snBt > 0) snBt--;
  uint32_t iv = (snLvl >= 10) ? 55 : (140 - snLvl * 9);
  if (millis() - snLast < iv) return;
  snLast = millis(); snDx = snNx; snDy = snNy;
  int nx = snX[0] + snDx, ny = snY[0] + snDy;
  if (nx < 0 || ny < 0 || nx >= SN_CW || ny >= SN_CH) { snDie(); return; }
  for (uint8_t i = 0; i < snStn; i++) if (stX[i] == nx && stY[i] == ny) { snDie(); return; }
  bool food = (nx == snFx && ny == snFy), bonus = (snBt > 0 && nx == snBx && ny == snBy), grow = food || bonus;
  uint16_t lim = grow ? snLen : snLen - 1;
  for (uint16_t i = 0; i < lim; i++) if (snX[i] == nx && snY[i] == ny) { snDie(); return; }
  if (grow && snLen < SN_MAX) snLen++;
  for (uint16_t i = snLen - 1; i > 0; i--) { snX[i] = snX[i - 1]; snY[i] = snY[i - 1]; }
  snX[0] = nx; snY[0] = ny;
  if (bonus) { snScore += 3; snBt = 0; fx(SFX_POWER, C_GOLD, 120); }
  if (food) {
    snScore++; snEat++; fx(SFX_COIN, C_GOOD, 70); snFx = 255; snPlace(snFx, snFy);
    if (snEat % 5 == 0 && snBt == 0) { snBt = 180; snPlace(snBx, snBy); }
    uint8_t nl = 1 + snEat / 6;
    if (nl > snLvl) { snLvl = nl; snAddStones(); bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); }
  }
}
static void snDraw() {
  char b[32]; u8g2.setFont(FONT_S);
  snprintf(b, sizeof b, "%u  LV%u  HI %u", snScore, snLvl, snHi); u8g2.drawStr(1, 7, b);
  if (snBt) u8g2.drawBox(100, 2, snBt / 6, 4);
  u8g2.drawFrame(0, 8, 128, 56);
  for (uint8_t i = 0; i < snStn; i++) { u8g2.drawFrame(stX[i] * 4, 8 + stY[i] * 4, 4, 4); u8g2.drawPixel(stX[i] * 4 + 1, 9 + stY[i] * 4); }
  for (uint16_t i = 0; i < snLen; i++) u8g2.drawBox(snX[i] * 4, 8 + snY[i] * 4, i ? 3 : 4, i ? 3 : 4);
  u8g2.drawBox(snFx * 4 + 1, 9 + snFy * 4, 2, 3); u8g2.drawBox(snFx * 4, 10 + snFy * 4, 4, 1);
  if (snBt) { if ((snBt / 6) & 1) u8g2.drawBox(snBx * 4, 8 + snBy * 4, 4, 4); else u8g2.drawFrame(snBx * 4, 8 + snBy * 4, 4, 4); }
  if (snDead) overBox(snScore, snHi);
}
static void snIcon(int x, int y) {
  for (int i = 0; i < 6; i++) u8g2.drawBox(x + 2 + i * 4, y + 20 - (i > 2 ? 8 : 0), 3, 3);
  for (int i = 0; i < 3; i++) u8g2.drawBox(x + 14, y + 12 + i * 4 + 4, 3, 3);
  u8g2.drawFrame(x + 24, y + 6, 5, 5); u8g2.drawBox(x + 4, y + 6, 4, 4);
}

#pragma once
// Road Racer - 4 lanes. Stick up/down = change lane, A = nitro, B = brake. Grab coins to refill nitro.
#define RC_ID 3
#define RC_N  7
struct RcV { float x, v; uint8_t lane, w, t; bool on; };   // t: 0 car, 1 truck, 2 coin
static RcV rV[RC_N];
static float rY, rSpd, rDist, rNitro, rOff;
static uint8_t rLane, rLevel; static uint16_t rScore, rHi, rCoins; static int16_t rCd; static bool rDead;
static inline int rLaneTop(uint8_t l) { return 8 + l * 14; }

static void rcInit() {
  rLane = 2; rY = rLaneTop(2) + 3; rSpd = 2.0f; rDist = 0; rNitro = 60; rOff = 0; rLevel = 1;
  rScore = 0; rCoins = 0; rCd = 40; rDead = false; rHi = hiGet(RC_ID);
  for (uint8_t i = 0; i < RC_N; i++) rV[i].on = false;
}
static void rcSpawn() {
  uint8_t lane = random(4); int busy = 0; bool laneBusy = false;
  for (uint8_t i = 0; i < RC_N; i++) if (rV[i].on && rV[i].x > 84) { busy++; if (rV[i].lane == lane) laneBusy = true; }
  bool coin = random(100) < 14;
  if (laneBusy || (!coin && busy >= 3)) return;
  for (uint8_t i = 0; i < RC_N; i++) if (!rV[i].on) {
    RcV &c = rV[i]; c.on = true; c.x = 128; c.lane = lane;
    if (coin) { c.t = 2; c.w = 6; c.v = 0; }
    else if (rLevel >= 2 && random(100) < 22) { c.t = 1; c.w = 26; c.v = 0.6f; }
    else { c.t = 0; c.w = 14; c.v = 0.8f + random(0, 8) / 10.0f; }
    return;
  }
}
static void rcUpdate() {
  if (rDead) { if (overKeys()) rcInit(); return; }
  if (in.py < 0 && rLane > 0) { rLane--; sfx(SFX_MOVE); }
  if (in.py > 0 && rLane < 3) { rLane++; sfx(SFX_MOVE); }
  float ty = rLaneTop(rLane) + 3;
  if (rY < ty) { rY += 3; if (rY > ty) rY = ty; } else if (rY > ty) { rY -= 3; if (rY < ty) rY = ty; }
  float base = 2.0f + rLevel * 0.3f; if (base > 5.5f) base = 5.5f; float tgt = base;
  bool boost = in.a && rNitro > 1;
  if (boost) { tgt = base + 2.2f; rNitro -= 1.0f; if (rNitro < 0) rNitro = 0; ledFlash(C_PURPLE, 60); }
  else { if (in.b) tgt = base - 1.0f < 1.0f ? 1.0f : base - 1.0f; rNitro += 0.12f; if (rNitro > 100) rNitro = 100; }
  rSpd += (tgt - rSpd) * 0.2f;
  rDist += rSpd * 0.08f * (boost ? 1.5f : 1.0f);
  uint8_t nl = 1 + (uint16_t)(rDist / 120);
  if (nl > rLevel) { rLevel = nl; bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); }
  rScore = (uint16_t)rDist + rCoins * 10;
  rOff += rSpd; if (rOff >= 16) rOff -= 16;
  if (--rCd <= 0) { rcSpawn(); rCd = (int)(random(20, 46) * 3.0f / (rSpd + 1.0f)); if (rCd < 8) rCd = 8; }
  for (uint8_t i = 0; i < RC_N; i++) {
    RcV &c = rV[i]; if (!c.on) continue;
    float sp = (c.t == 2) ? rSpd : (rSpd - c.v < 0.5f ? 0.5f : rSpd - c.v);
    c.x -= sp; if (c.x + c.w < 0) { c.on = false; continue; }
    float cy = rLaneTop(c.lane) + 3;
    if (hitBox(15, rY + 1, 12, 6, c.x + 1, cy + 1, c.w - 2, 6)) {
      if (c.t == 2) { c.on = false; rCoins++; rNitro += 25; if (rNitro > 100) rNitro = 100; fx(SFX_COIN, C_GOLD, 100); }
      else { rDead = true; endRun(RC_ID, rScore, rHi); }
    }
  }
}
static void rcDraw() {
  u8g2.drawHLine(0, 8, 128); u8g2.drawHLine(0, 63, 128);
  for (int l = 1; l < 4; l++) for (int x = -(int)rOff; x < 128; x += 16) u8g2.drawHLine(x, 8 + l * 14, 8);
  for (uint8_t i = 0; i < RC_N; i++) {
    if (!rV[i].on) continue;
