static bool g2048Spawn() { uint8_t empty=0; for(int y=0;y<4;y++)for(int x=0;x<4;x++)if(!g2048[y][x])empty++; if(!empty)return false; uint8_t n=random(empty); for(int y=0;y<4;y++)for(int x=0;x<4;x++)if(!g2048[y][x]&&n--==0){g2048[y][x]=(random(10)==0)?4:2;return true;} return false; }
