#ifndef ESP_ARDUINO_VERSION_MAJOR
#define ESP_ARDUINO_VERSION_MAJOR 2
#endif

#define FONT_S u8g2_font_5x7_tf
#define FONT_M u8g2_font_6x10_tf
// colour shortcuts: fx(SFX_COIN, C_GOLD, 80)
#define C_GOOD   0,255,0
#define C_BAD    255,0,0
#define C_GOLD   255,190,0
#define C_CYAN   0,200,255
#define C_WHITE  255,255,255
#define C_PURPLE 170,0,255
#define C_ORANGE 255,100,0

static inline int imin(int a, int b) { return a < b ? a : b; }
static inline int imax(int a, int b) { return a > b ? a : b; }
static inline bool hitBox(float ax, float ay, float aw, float ah, float bx, float by, float bw, float bh) {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

static U8G2_SSD1306_128X64_NONAME_F_HW_I2C u8g2(U8G2_R2, U8X8_PIN_NONE);
static bool gotoMenu = false;   // a game sets this to go back to the launcher

static void displayInit() {
  Wire.setPins(PIN_SDA, PIN_SCL);
  u8g2.begin();
  u8g2.setBusClock(I2C_HZ);
  u8g2.setFont(FONT_M);
}
static void textC(const char* s, int y) { u8g2.drawStr((128 - u8g2.getStrWidth(s)) / 2, y, s); }

// ================================================================ settings (saved in flash)
struct Cfg { bool sound; };
static Cfg cfg = {true};
static const uint8_t LED_LEVELS[4] = {0, 12, 40, 110};
static void cfgLoad() {
  Preferences p; p.begin("cfg", false);
  cfg.sound = p.getUChar("snd", 1);
  p.end();
}
static void cfgSave() {
  Preferences p; p.begin("cfg", false);
  p.putUChar("snd", cfg.sound);
  p.end();
}

// ================================================================ input
struct Input {
  int8_t dx, dy;        // held: -1/0/+1 (dy -1 = up) - hysteresis + dominant-axis filtered
  int8_t px, py;        // first press of a direction
  int8_t rx, ry;        // press + auto-repeat (menus, tetris)
  int8_t ax, ay;        // analog, dead-zoned + curved + smoothed: -100..+100 (use for cursors / paddles / ships)
  bool a, b, sw, touch;
  bool aP, bP, swP, touchP;
};
static Input in;
// joyC* = centre (calibrated, slowly self-corrects), joyF* = smoothed reading <<4, joyR* = filtered offset from centre
static int joyCx = 2048, joyCy = 2048, joyRx = 0, joyRy = 0, joyRawX = 0, joyRawY = 0;
static int joyFx = 2048 << 4, joyFy = 2048 << 4;

static int joyRead(uint8_t pin) { return (analogRead(pin) + analogRead(pin) + 1) >> 1; }   // 2-sample average
static void inputCalibrate() {
  int cx = 2048, cy = 2048;
  for (uint8_t tryN = 0; tryN < 3; tryN++) {      // retry if the stick was moving while sampling
    long sx = 0, sy = 0; int x0 = 4095, x1 = 0, y0 = 4095, y1 = 0;
    for (int i = 0; i < 40; i++) {
      int x = joyRead(PIN_JOY_X), y = joyRead(PIN_JOY_Y); sx += x; sy += y;
      x0 = imin(x0, x); x1 = imax(x1, x); y0 = imin(y0, y); y1 = imax(y1, y); delay(2);
    }
    cx = sx / 40; cy = sy / 40;
    if (x1 - x0 < 120 && y1 - y0 < 120) break;
  }
  if (cx < 1200 || cx > 2900) cx = 2048;           // stick was held at boot -> fall back to nominal centre
  if (cy < 1200 || cy > 2900) cy = 2048;
  joyCx = cx; joyCy = cy; joyFx = cx << 4; joyFy = cy << 4; joyRx = joyRy = 0;
}
static void inputInit() {
  pinMode(PIN_BTN_A, INPUT_PULLUP); pinMode(PIN_BTN_B, INPUT_PULLUP);
  pinMode(PIN_JOY_SW, INPUT_PULLUP); pinMode(PIN_TOUCH, INPUT);
  inputCalibrate();
}
static void repeatAxis(int8_t d, int8_t &prev, uint32_t &next, int8_t &out) {
  out = 0; uint32_t now = millis();
  if (d == 0) { prev = 0; return; }
  if (d != prev) { prev = d; out = d; next = now + 220; }
  else if ((int32_t)(now - next) >= 0) { out = d; next = now + 90; }
}
// offset from centre (counts) -> -100..100: dead zone, then 35% linear + 65% squared (fine control near centre, full speed at the edge)
static int8_t joyShape(int r) {
  int a = r < 0 ? -r : r;
  if (a <= JOY_DEAD) return 0;
  int span = JOY_RANGE - JOY_DEAD; a -= JOY_DEAD; if (a > span) a = span;
  int n = a * 100 / span, o = (n * 35 + n * n * 65 / 100) / 100;
  if (o < 1) o = 1;
  return r < 0 ? -o : o;
}
static void joyTrack(int raw, int &f, int &c, int &r, uint8_t &idle, bool slow) {   // smooth + self-centre one axis
  f += ((raw << 4) - f) * JOY_FILT / 8;
  int v = (f + 8) >> 4; r = v - c;
  if (r > -(JOY_DEAD * 2 / 3) && r < JOY_DEAD * 2 / 3) {      // resting: creep the centre toward the reading (drift fix)
    if (idle < 60) idle++; else if (slow) c += (v > c) - (v < c);
  } else idle = 0;
  r = v - c;
}
static void inputUpdate() {
  static bool pa = false, pb = false, ps = false, tHeld = false, tFired = false;
  static int8_t pdx = 0, pdy = 0, rpx = 0, rpy = 0;
  static uint32_t nx = 0, ny = 0, tStart = 0; static uint8_t idX = 0, idY = 0, tick = 0;
  joyRawX = joyRead(PIN_JOY_X); joyRawY = joyRead(PIN_JOY_Y); tick++;
  int rx, ry; bool slow = (tick & 3) == 0;
  joyTrack(joyRawX, joyFx, joyCx, rx, idX, slow); joyTrack(joyRawY, joyFy, joyCy, ry, idY, slow);
#if JOY_SWAP_XY
  { int t = rx; rx = ry; ry = t; }
#endif
#if JOY_INVERT_X
  rx = -rx;
#endif
#if JOY_INVERT_Y
  ry = -ry;
#endif
  joyRx = rx; joyRy = ry;
  in.ax = joyShape(rx); in.ay = joyShape(ry);
  int ax = rx < 0 ? -rx : rx, ay = ry < 0 ? -ry : ry;
  int tx = pdx ? JOY_THRESH - JOY_HYST : JOY_THRESH, ty = pdy ? JOY_THRESH - JOY_HYST : JOY_THRESH;
  bool onX = ax > tx, onY = ay > ty;
  if (onX && onY) { if (ax * 2 < ay * 3 && ay * 2 < ax * 3) {} else if (ax > ay) onY = false; else onX = false; }   // diagonal only when near 45 deg
  in.dx = onX ? (rx > 0 ? 1 : -1) : 0;
  in.dy = onY ? (ry > 0 ? 1 : -1) : 0;
  in.px = (in.dx != 0 && in.dx != pdx) ? in.dx : 0; pdx = in.dx;
  in.py = (in.dy != 0 && in.dy != pdy) ? in.dy : 0; pdy = in.dy;
  repeatAxis(in.dx, rpx, nx, in.rx); repeatAxis(in.dy, rpy, ny, in.ry);
#if BTN_SWAP_AB
  in.a  = !digitalRead(PIN_BTN_B);  in.aP  = in.a  && !pa; pa = in.a;
  in.b  = !digitalRead(PIN_BTN_A);  in.bP  = in.b  && !pb; pb = in.b;
#else
  in.a  = !digitalRead(PIN_BTN_A);  in.aP  = in.a  && !pa; pa = in.a;
  in.b  = !digitalRead(PIN_BTN_B);  in.bP  = in.b  && !pb; pb = in.b;
#endif
  in.sw = !digitalRead(PIN_JOY_SW); in.swP = in.sw && !ps; ps = in.sw;
  in.touch = digitalRead(PIN_TOUCH); in.touchP = false;      // touch must be held ~120 ms (ignores accidental brushes)
  if (in.touch) {
    if (!tHeld) { tHeld = true; tStart = millis(); }
    if (!tFired && millis() - tStart >= 120) { tFired = true; in.touchP = true; }
  } else { tHeld = false; tFired = false; }
}

// ================================================================ sound engine
// Tones are kept in the 1.5-4.2 kHz range: small buzzers are LOUD there and very quiet below ~1 kHz.
enum Sfx : uint8_t { SFX_NONE, SFX_MOVE, SFX_SELECT, SFX_BACK, SFX_JUMP, SFX_COIN, SFX_HIT, SFX_SHOOT,
                     SFX_BOOM, SFX_POWER, SFX_LEVEL, SFX_OVER, SFX_BEST, SFX_START, SFX_LINE, SFX_DUCK, SFX_BOOT, SFX_COUNT };
struct Note { uint16_t f, ms; };   // {0,0} ends a sequence
static const Note S_MOVE[]   = {{2600,10},{0,0}};
static const Note S_SELECT[] = {{2200,35},{3200,55},{0,0}};
static const Note S_BACK[]   = {{3000,35},{2000,55},{0,0}};
static const Note S_JUMP[]   = {{1800,22},{2600,32},{0,0}};
static const Note S_COIN[]   = {{3300,30},{4200,80},{0,0}};
static const Note S_HIT[]    = {{2200,40},{1400,60},{900,110},{0,0}};
static const Note S_SHOOT[]  = {{3900,12},{3000,12},{0,0}};
static const Note S_BOOM[]   = {{1500,35},{900,45},{500,70},{300,120},{0,0}};
static const Note S_POWER[]  = {{2000,40},{2600,40},{3200,40},{3900,90},{0,0}};
static const Note S_LEVEL[]  = {{2200,70},{2800,70},{3400,70},{4200,150},{0,0}};
static const Note S_OVER[]   = {{2600,130},{2100,130},{1700,130},{1100,320},{0,0}};
static const Note S_BEST[]   = {{2500,90},{3100,90},{3700,90},{3100,70},{4200,250},{0,0}};
static const Note S_START[]  = {{2200,60},{3000,60},{4000,100},{0,0}};
static const Note S_LINE[]   = {{2800,50},{3400,50},{4000,110},{0,0}};
static const Note S_DUCK[]   = {{1500,20},{1100,25},{0,0}};
static const Note S_BOOT[]   = {{1700,70},{2300,70},{2900,70},{0,40},{3400,60},{4200,220},{0,0}};
static const Note* const SFX_TAB[] = {nullptr, S_MOVE, S_SELECT, S_BACK, S_JUMP, S_COIN, S_HIT, S_SHOOT,
                                      S_BOOM, S_POWER, S_LEVEL, S_OVER, S_BEST, S_START, S_LINE, S_DUCK, S_BOOT};
static const uint8_t SFX_PRI[] = {0, 1, 2, 2, 1, 2, 2, 0, 2, 2, 3, 3, 3, 2, 2, 1, 3};
static_assert(sizeof(SFX_TAB) / sizeof(SFX_TAB[0]) == SFX_COUNT, "sfx table size");

static const Note* seq = nullptr; static uint32_t seqNext = 0; static uint8_t seqPri = 0;
static Note dynNote[2];

// ================================================================ audio output disabled (no buzzer GPIO used)
static void toneWrite(uint16_t) {}
static void audioInit() {}
static void audioStop() { seq = nullptr; seqPri = 0; }
static void sfxPlay(const Note*, uint8_t) {}
static void sfx(Sfx) {}
static void sfxTone(uint16_t, uint16_t) {}
static void audioUpdate() {}

// ================================================================ LED output disabled (no LED GPIO used)
static uint8_t ledBase[3] = {0, 0, 0};
static uint32_t ledFlashEnd = 0;
static void ledApply(uint8_t, uint8_t, uint8_t) {}
static void ledReset() {}
static void ledSetBase(uint8_t r, uint8_t g, uint8_t b) { ledBase[0] = r; ledBase[1] = g; ledBase[2] = b; }
static void ledFlash(uint8_t, uint8_t, uint8_t, uint16_t ms) { ledFlashEnd = millis() + ms; }
static void ledUpdate() { if (ledFlashEnd && (int32_t)(millis() - ledFlashEnd) >= 0) ledFlashEnd = 0; }
static void fx(Sfx s, uint8_t, uint8_t, uint8_t, uint16_t = 120) { sfx(s); }

// ================================================================ high scores
static uint16_t hiGet(uint8_t id) {
  char k[8]; snprintf(k, sizeof k, "g%u", id);
  Preferences p; p.begin("hs", false); uint16_t v = p.getUShort(k, 0); p.end(); return v;
}
static void hiSet(uint8_t id, uint16_t v) {
  char k[8]; snprintf(k, sizeof k, "g%u", id);
  Preferences p; p.begin("hs", false); p.putUShort(k, v); p.end();
}

// ================================================================ UI helpers
static char toastMsg[20]; static uint32_t toastUntil = 0;
static char bannerMsg[16]; static uint32_t bannerUntil = 0;
static void toast(const char* m) { strncpy(toastMsg, m, 19); toastMsg[19] = 0; toastUntil = millis() + 1300; }
static void banner(const char* m) { strncpy(bannerMsg, m, 15); bannerMsg[15] = 0; bannerUntil = millis() + 1300; }
static void bannerLevel(uint16_t lv) { char b[16]; snprintf(b, sizeof b, "LEVEL %u", lv); banner(b); }
static void toastDraw() {
  if (!toastUntil) return;
  if ((int32_t)(millis() - toastUntil) >= 0) { toastUntil = 0; return; }
  u8g2.setFont(FONT_S); int w = u8g2.getStrWidth(toastMsg) + 8, x = (128 - w) / 2;
  u8g2.setDrawColor(0); u8g2.drawBox(x, 52, w, 11); u8g2.setDrawColor(1);
  u8g2.drawFrame(x, 52, w, 11); u8g2.drawStr(x + 4, 60, toastMsg);
}
static void bannerDraw() {
  if (!bannerUntil) return;
  if ((int32_t)(millis() - bannerUntil) >= 0) { bannerUntil = 0; return; }
  u8g2.setFont(FONT_M); int w = u8g2.getStrWidth(bannerMsg) + 14, x = (128 - w) / 2;
  u8g2.setDrawColor(0); u8g2.drawBox(x, 22, w, 18); u8g2.setDrawColor(1);
  u8g2.drawFrame(x, 22, w, 18); textC(bannerMsg, 35);
}
static void drawSpeaker(int x, int y, bool on) {   // 9x7 icon in the current draw colour
  u8g2.drawBox(x, y + 2, 2, 3); u8g2.drawBox(x + 2, y + 1, 1, 5); u8g2.drawBox(x + 3, y, 1, 7);
  if (on) { u8g2.drawPixel(x + 5, y + 2); u8g2.drawPixel(x + 5, y + 4); u8g2.drawPixel(x + 6, y + 1); u8g2.drawPixel(x + 6, y + 5); }
  else { for (int i = 0; i < 4; i++) { u8g2.drawPixel(x + 5 + i, y + 1 + i); u8g2.drawPixel(x + 5 + i, y + 5 - i); } }
}
static void overlay(const char* l1, const char* l2) {
  u8g2.setDrawColor(0); u8g2.drawBox(14, 16, 100, 32);
  u8g2.setDrawColor(1); u8g2.drawFrame(14, 16, 100, 32);
  u8g2.setFont(FONT_M); textC(l1, 31); u8g2.setFont(FONT_S); textC(l2, 42);
}

// ---- common "run finished" handling
static uint32_t overAt = 0; static bool newBest = false;
static void endRun(uint8_t id, uint16_t score, uint16_t &hi) {
  newBest = score > hi; if (newBest) { hi = score; hiSet(id, score); }
  overAt = millis();
  if (newBest) fx(SFX_BEST, C_GOLD, 700); else fx(SFX_OVER, C_BAD, 500);
}
static bool overKeys() {                 // true = restart. B goes back to the menu.
  if (millis() - overAt < 500) return false;
  if (in.bP) { gotoMenu = true; return false; }
  return in.aP;
}
static void overBox(uint16_t score, uint16_t hi) {
  u8g2.setDrawColor(0); u8g2.drawBox(10, 8, 108, 48);
  u8g2.setDrawColor(1); u8g2.drawFrame(10, 8, 108, 48);
  char b[28]; u8g2.setFont(FONT_M); textC("GAME OVER", 20);
  u8g2.setFont(FONT_S); snprintf(b, sizeof b, "SCORE %u   BEST %u", score, hi); textC(b, 30);
  if (newBest && ((millis() / 300) & 1)) textC("* NEW BEST! *", 39);
  textC("A:again   B:menu", 51);
}

// ARCADE - multi-game console for ESP32-C3 Super Mini + 128x64 SSD1306 OLED
// Library needed: "U8g2" by olikraus (Library Manager). Board: ESP32C3 Dev Module, USB CDC On Boot: Enabled.
// Pins / options: config.h.  Add games: games.h.
//
// CONTROLS
//   Stick       move / navigate           A  = main action (select, jump, fire...)
//   B           secondary (duck, bomb...)  Stick click (SW) = PAUSE MENU (resume / restart / sound / quit)
//   Touch pad   mute / unmute (hold ~0.2 s)
#include "hal.h"
#include "games.h"

enum Mode : uint8_t { MODE_MENU, MODE_INTRO, MODE_PLAY, MODE_PAUSE };
static Mode     mode = MODE_MENU;
static uint8_t  sel = 0, cur = 0, pauseSel = 0;
static uint32_t menuLock = 0;       // ignore input briefly after entering the menu (no accidental launch)
static int16_t  menuTarget = 0;      // unbounded card index so wrap-around animates smoothly
static float    menuPos = 0;         // animated position (card units)
static uint16_t hiCache[24];

static void enterMenu() {
  mode = MODE_MENU; audioStop(); bannerUntil = 0; toastUntil = 0; gotoMenu = false; ledFlashEnd = 0; overAt = 0;
  sel = cur; menuTarget = sel; menuPos = sel; menuLock = millis() + 200;
  for (uint8_t i = 0; i < NGAMES && i < 24; i++) hiCache[i] = GAMES[i].kind ? 0 : hiGet(i);
  ledSetBase(GAMES[sel].r, GAMES[sel].g, GAMES[sel].b);
}
static void startGame(uint8_t i) {
  cur = i; mode = MODE_PLAY; bannerUntil = 0; toastUntil = 0; gotoMenu = false;
  ledSetBase(GAMES[i].r, GAMES[i].g, GAMES[i].b);
  GAMES[i].init(); fx(SFX_START, C_WHITE, 150);
}

// ------------------------------------------------------------------ launcher
static void menuInput() {
  if ((int32_t)(millis() - menuLock) < 0) return;
  int8_t d = in.rx ? in.rx : in.ry;
  if (d) {
    menuTarget += d; sel = ((menuTarget % NGAMES) + NGAMES) % NGAMES; sfx(SFX_MOVE);
    ledSetBase(GAMES[sel].r, GAMES[sel].g, GAMES[sel].b);
  }
  if (in.aP || in.swP) {
    sfx(SFX_SELECT);
    if (GAMES[sel].kind) startGame(sel); else { cur = sel; mode = MODE_INTRO; }
  }
}
static void menuCard(int cx, int y, uint8_t g, float near) {   // near: 1 = selected .. 0 = side card
  int x = cx - 18;
  if (near > 0.6f) {
    u8g2.drawRFrame(x, y, 36, 36, 3);
    if ((millis() / 400) & 1) u8g2.drawRFrame(x - 1, y - 1, 38, 38, 4);    // blinking selection halo
    GAMES[g].icon(x + 2, y + 2);
  } else {
    u8g2.drawRFrame(x + 2, y + 2, 32, 32, 3); GAMES[g].icon(x + 2, y + 2);
    u8g2.setDrawColor(0);   // dim side cards with a checker mask
    for (int j = 0; j < 36; j += 2) for (int i = (j >> 1) & 1; i < 36; i += 2) u8g2.drawPixel(x + i, y + j);
    u8g2.setDrawColor(1);
  }
}
static void menuDraw() {
  if (!ledFlashEnd) {
    float k = 0.45f + 0.55f * (0.5f + 0.5f * sinf(millis() / 350.0f));
    ledApply((uint8_t)(GAMES[sel].r * k), (uint8_t)(GAMES[sel].g * k), (uint8_t)(GAMES[sel].b * k));
  }
  menuPos += (menuTarget - menuPos) * 0.38f; if (fabsf(menuTarget - menuPos) < 0.02f) menuPos = menuTarget;
  char b[16];
  u8g2.setFont(FONT_S); u8g2.setDrawColor(1); u8g2.drawBox(0, 0, 128, 9); u8g2.setDrawColor(0);
  u8g2.drawStr(2, 7, "ARCADE"); snprintf(b, sizeof b, "%u/%u", sel + 1, NGAMES); u8g2.drawStr(64 - u8g2.getStrWidth(b) / 2, 7, b);
  if (hiCache[sel]) { snprintf(b, sizeof b, "HI %u", hiCache[sel]); u8g2.drawStr(126 - 14 - u8g2.getStrWidth(b) - 4, 7, b); }
  drawSpeaker(117, 1, cfg.sound); u8g2.setDrawColor(1);
  int base = (int)floorf(menuPos);
  for (int i = base - 1; i <= base + 2; i++) {
    float d = i - menuPos, ad = fabsf(d);
    if (ad > 1.7f) continue;
    uint8_t g = ((i % NGAMES) + NGAMES) % NGAMES;
    menuCard(64 + (int)(d * 46), 11 + (ad > 1 ? 3 : (int)(ad * 3)), g, ad < 0.5f ? 1.0f : 0.0f);
  }
  u8g2.setFont(FONT_M); textC(GAMES[sel].name, 55);
  u8g2.setFont(FONT_S); textC(GAME_DESC[sel], 63);
}

// ------------------------------------------------------------------ intro card (controls)
static void introInput() {
  if (in.bP) { sfx(SFX_BACK); enterMenu(); }
  else if (in.aP || in.swP) startGame(cur);
}
static void introDraw() {
  const Game& g = GAMES[cur];
  u8g2.setDrawColor(1); u8g2.drawBox(0, 0, 128, 11); u8g2.setDrawColor(0); u8g2.setFont(FONT_M); textC(g.name, 9); u8g2.setDrawColor(1);
  u8g2.drawFrame(2, 14, 36, 36); g.icon(4, 16);
  u8g2.setFont(FONT_S);
  u8g2.drawStr(42, 22, g.help1); u8g2.drawStr(42, 31, g.help2); u8g2.drawStr(42, 40, "SW: pause menu");
  char b[16]; snprintf(b, sizeof b, "BEST %u", hiCache[cur]); u8g2.drawStr(42, 49, b);
  u8g2.drawHLine(0, 53, 128); u8g2.drawStr(2, 62, "A:START"); u8g2.drawStr(128 - 7 * 5 - 2, 62, "B:BACK");
}

// ------------------------------------------------------------------ play + pause
static void playInput() {
  if (GAMES[cur].kind) { if (in.swP || gotoMenu) { gotoMenu = false; sfx(SFX_BACK); enterMenu(); } else GAMES[cur].update(); return; }
  if (in.swP) { mode = MODE_PAUSE; pauseSel = 0; audioStop(); sfx(SFX_SELECT); return; }
  if (gotoMenu) { gotoMenu = false; sfx(SFX_BACK); enterMenu(); return; }
  GAMES[cur].update();
}
static void pauseInput() {
  if (in.py < 0) { pauseSel = (pauseSel + 3) % 4; sfx(SFX_MOVE); }
  if (in.py > 0) { pauseSel = (pauseSel + 1) % 4; sfx(SFX_MOVE); }
  if (in.bP) { mode = MODE_PLAY; sfx(SFX_BACK); return; }
  if (!in.aP && !in.swP) return;                // A or stick-click confirms the highlighted item
  switch (pauseSel) {
    case 0: mode = MODE_PLAY; sfx(SFX_BACK); break;
    case 1: GAMES[cur].init(); mode = MODE_PLAY; fx(SFX_START, C_WHITE, 150); break;
    case 2: cfg.sound = !cfg.sound; cfgSave(); if (!cfg.sound) audioStop(); else sfx(SFX_SELECT); break;
    default: sfx(SFX_BACK); enterMenu();
  }
}
static void pauseDraw() {
  u8g2.setDrawColor(0); u8g2.drawBox(22, 4, 84, 57); u8g2.setDrawColor(1); u8g2.drawFrame(22, 4, 84, 57);
  u8g2.setFont(FONT_M); textC("PAUSED", 15); u8g2.setFont(FONT_S);
  const char* it[4] = {"Resume", "Restart", cfg.sound ? "Sound: ON" : "Sound: OFF", "Quit to menu"};
  for (uint8_t i = 0; i < 4; i++) {
    int y = 27 + i * 9; bool on = (i == pauseSel);
    if (on) u8g2.drawBox(26, y - 7, 76, 9);
    u8g2.setDrawColor(on ? 0 : 1); u8g2.drawStr(30, y, it[i]); u8g2.setDrawColor(1);
  }
}

// ------------------------------------------------------------------ boot
// scaled gamepad logo (s = 0..1.3), centred at cx,cy
static void bootLogo(int cx, int cy, float s) {
  int w = (int)(26 * s), h = (int)(14 * s); if (w < 2) return;
  u8g2.drawRBox(cx - w, cy - h, w * 2, h * 2, imax(1, (int)(5 * s)));
  u8g2.setDrawColor(0);
  int px = cx - w * 5 / 8, dp = imax(1, (int)(2 * s));                  // d-pad
  u8g2.drawBox(px - dp * 2, cy - dp / 2, dp * 4 + 1, dp); u8g2.drawBox(px - dp / 2, cy - dp * 2, dp, dp * 4 + 1);
  u8g2.drawDisc(cx + w / 2, cy - h / 4, imax(1, (int)(2 * s))); u8g2.drawDisc(cx + w * 3 / 4, cy + h / 5, imax(1, (int)(2 * s)));
  u8g2.drawBox(cx - w / 4, cy + h / 3, imax(1, w / 5), imax(1, dp / 2)); u8g2.drawBox(cx, cy + h / 3, imax(1, w / 5), imax(1, dp / 2));
  u8g2.setDrawColor(1);
}
static void bootShutter(uint32_t ms, bool open, bool menu) {   // black bars close (logo) or open (menu) from the middle
  uint32_t t0 = millis();
  for (;;) {
    uint32_t e = millis() - t0; if (e >= ms) break;
    int w = (int)(64L * e / ms); if (open) w = 64 - w;
    u8g2.clearBuffer();
    if (menu) menuDraw(); else { bootLogo(64, 24, 1.0f); u8g2.setFont(FONT_M); textC("ARCADE", 52); }
    u8g2.setDrawColor(0);
    if (menu) { u8g2.drawBox(0, 0, w, 64); u8g2.drawBox(128 - w, 0, w, 64); }          // curtains parting toward the edges
    else { u8g2.drawBox(0, 0, 128, w / 2); u8g2.drawBox(0, 64 - w / 2, 128, w / 2); }   // lids closing on the logo
    u8g2.setDrawColor(1); u8g2.sendBuffer(); audioUpdate();
  }
}
void setup() {
  cfgLoad(); randomSeed(esp_random());
  displayInit(); inputInit(); audioInit();
  ledApply(0, 0, 0); sfx(SFX_BOOT);
  static uint8_t pX[14], pY[14], pS[14];                       // sparkle particles
  for (uint8_t i = 0; i < 14; i++) { pX[i] = random(128); pY[i] = random(64); pS[i] = 1 + random(3); }
  const uint32_t T = 1700; uint32_t t0 = millis(), e;
  while ((e = millis() - t0) < T) {
    u8g2.clearBuffer();
    for (uint8_t i = 0; i < 14; i++) {                         // particles drift up, twinkle
      pY[i] = (pY[i] + 64 - pS[i] / 2) & 63; if (((e / 90) + i) % 3) u8g2.drawPixel(pX[i], pY[i]);
    }
    float p = e / 650.0f; if (p > 1) p = 1;                     // ease-out-back pop-in
    float q = p - 1, s = 1 + 2.70158f * q * q * q + 1.70158f * q * q;
    int cy = 24, r = (int)(16 + 30 * (e / (float)T));           // expanding dotted glow ring
    if (e > 150) for (int a = 0; a < 48; a += 1) if (((a + e / 40) & 3) == 0) {
      float an = a * 0.1309f; int x = 64 + (int)(cosf(an) * r * 1.6f), y = cy + (int)(sinf(an) * r); if (x >= 0 && x < 128 && y >= 0 && y < 64) u8g2.drawPixel(x, y);
    }
    bootLogo(64, cy, s);
    if (e > 600) {                                               // wordmark pops in with stepped font sizes
      u8g2.setFont(e < 700 ? u8g2_font_6x10_tf : (e < 800 ? u8g2_font_helvB10_tf : u8g2_font_helvB14_tf)); textC("ARCADE", e < 700 ? 50 : (e < 800 ? 52 : 56));
    }
    if (e > 1000) { u8g2.setFont(FONT_S); textC("ESP32-C3 GAME CONSOLE", 63); }
    int sy = (int)((e * 3) % 190) - 30;                          // scanline sweep with dither trail
    if (sy >= 0 && sy < 64) { u8g2.setDrawColor(2); u8g2.drawHLine(0, sy, 128); u8g2.setDrawColor(1); for (int x = sy & 1; x < 128; x += 2) if (sy > 2) u8g2.drawPixel(x, sy - 2); }
    u8g2.sendBuffer();
    uint8_t k = (uint8_t)(220 * (e < 650 ? e / 650.0f : 1.0f - (e - 650) / (float)(T - 650) * 0.6f)); ledApply(k / 3, k / 2, k);
    audioUpdate();
  }
  bootShutter(220, false, false);
  ledApply(0, 0, 0); enterMenu();
  bootShutter(300, true, true);
}

void loop() {
  uint32_t t0 = millis();
  inputUpdate(); audioUpdate(); ledUpdate();
  if (in.touchP) {
    cfg.sound = !cfg.sound; cfgSave();
    if (!cfg.sound) audioStop(); else sfx(SFX_SELECT);
    toast(cfg.sound ? "SOUND ON" : "SOUND OFF");
  }
  switch (mode) {
    case MODE_MENU:  menuInput();  break;
    case MODE_INTRO: introInput(); break;
    case MODE_PLAY:  playInput();  break;
    default:         pauseInput();
  }
  u8g2.clearBuffer();
  switch (mode) {
    case MODE_MENU:  menuDraw();  break;
    case MODE_INTRO: introDraw(); break;
    case MODE_PLAY:  GAMES[cur].draw(); break;
    default:         GAMES[cur].draw(); pauseDraw();
  }
  toastDraw(); bannerDraw();
  u8g2.sendBuffer();
  while (millis() - t0 < FRAME_MS) delay(1);
}

#pragma once
// Bouncing Ball - gravity ball, return it with the paddle (stick left/right). Every 5 returns: higher gravity = faster ball,
// narrower paddle. Hit with the paddle edge to steer the ball. Miss = game over.
#define BB_ID 8
static float bbX, bbY, bbVx, bbVy, bbG, bbPx; static uint8_t bbLvl, bbTr[5][2]; static uint16_t bbScore, bbHi;
static bool bbOver; static uint32_t bbServe; static uint8_t bbFlash;
static int bbPw() { int w = 24 - 2 * (bbLvl - 1); return w < 12 ? 12 : w; }
static void bbInit() {
  bbPx = 54; bbLvl = 1; bbG = 0.20f; bbScore = 0; bbOver = false; bbHi = hiGet(BB_ID); bbFlash = 0;
  bbX = 20 + random(88); bbY = 12; bbVx = random(2) ? 0.8f : -0.8f; bbVy = 0; bbServe = millis() + 600;
  for (uint8_t i = 0; i < 5; i++) { bbTr[i][0] = bbX; bbTr[i][1] = bbY; }
}
static void bbUpdate() {
  if (bbOver) { if (overKeys()) bbInit(); return; }
  int pw = bbPw(); bbPx += in.ax * 0.07f; if (bbPx < 0) bbPx = 0; if (bbPx > 128 - pw) bbPx = 128 - pw;
  if (bbFlash) bbFlash--;
  if ((int32_t)(millis() - bbServe) < 0) return;
  for (uint8_t i = 4; i > 0; i--) { bbTr[i][0] = bbTr[i - 1][0]; bbTr[i][1] = bbTr[i - 1][1]; }
  bbTr[0][0] = (uint8_t)bbX; bbTr[0][1] = (uint8_t)bbY;
  bbVy += bbG; bbX += bbVx; bbY += bbVy;
  if (bbX < 2) { bbX = 2; bbVx = -bbVx; sfx(SFX_MOVE); } if (bbX > 125) { bbX = 125; bbVx = -bbVx; sfx(SFX_MOVE); }
  if (bbY < 11) { bbY = 11; bbVy = -bbVy * 0.8f; sfx(SFX_MOVE); }
  if (bbVy > 0 && bbY >= 56 && bbY - bbVy <= 60 && bbX + 2 >= bbPx && bbX - 2 <= bbPx + pw) {   // paddle return
    float off = (bbX - (bbPx + pw / 2.0f)) / (pw / 2.0f + 2);                                // -1..1
    bbY = 56; bbVy = -sqrtf(2 * bbG * 46.0f);                                               // peak ~46 px, any gravity
    bbVx = off * (2.2f + 0.12f * bbLvl) + in.ax * 0.012f; if (bbVx > 4) bbVx = 4; if (bbVx < -4) bbVx = -4;
    bbScore++; bbFlash = 4; uint8_t nl = 1 + bbScore / 5;
